plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
com.2t5.deck-plus
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
11.0.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}

NSAppleEventsUsageDescription
2T5 DECK+ asks Finder which files are selected so the deck's colour buttons can tag them.
NSDesktopFolderUsageDescription
2T5 DECK+ applies Finder colour tags to files you select on the Desktop.
NSDocumentsFolderUsageDescription
2T5 DECK+ applies Finder colour tags to files you select in Documents.
NSDownloadsFolderUsageDescription
2T5 DECK+ applies Finder colour tags to files you select in Downloads.
NSRemovableVolumesUsageDescription
2T5 DECK+ applies Finder colour tags to files you select on external drives.
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.wails.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
NSAppTransportSecurity

    NSAllowsLocalNetworking
